SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);Alarm(600);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");Attach("work/deg10/continuation_20261029/deps/fast_hecke_11.m");Attach(root cat "inputs/fast_full_aut_hash_m3_18_root.m");k:=GF(7);X:=MDX11(3,18,k);C:=Curve(X);FF:=FunctionField(C);F,mp:=AlgorithmicFunctionField(FF);B:=BaseField(F);u:=F!B.1;du:=Differential(u);tf:=eval Read(root cat "tau_frame_p7.m");PK:=PolynomialRing(k);
function DR(a)return B!(PK!a[1])/(B!(PK!a[2]));end function;function DF(a)return F![DR(c):c in a];end function;
assert Coefficients(DefiningPolynomial(F))eq[DR(a):a in tf[1]];bm:=hom<B->F|DF(tf[3][2])>;tau:=hom<F->F|bm,DF(tf[3][1])>;
E:=EllipticCurve(X`_E);P:=E!X`_P;Q:=E!X`_Q;pars:=which eq 12 select[1,2,0,1]else[1,2,1,1];inv:=which eq 12 select[1,1,0,1]else[2,2,1,5];
function Aut(par)a,b,c,d:=Explode(par);qf,tf:=Explode(M3EighteenRootNormalizedPair(E,a*P+6*b*Q,c*P+d*Q));XY:=[mp(qf)-1,mp(tf)*mp(qf)/(mp(qf)-1)];function Sub(f)ff:=f@@mp;nn:=Numerator(ff);dd:=Denominator(ff);args:=Rank(Parent(nn))eq 3 select XY cat[F!1]else XY;return Evaluate(nn,args)/Evaluate(dd,args);end function;bm:=hom<B->F|Sub(F!B.1)>;return hom<F->F|bm,Sub(F.1)>;end function;
ag:=Aut(pars);ai:=Aut(inv);assert &and[ag(ai(f))eq f:f in[F.1,u]];hv:=ag(tau(ai(F.1)));hu:=ag(tau(ai(u)));hm:=hom<B->F|hu>;h:=hom<F->F|hm,hv>;assert &and[h(h(f))eq f:f in[F.1,u]];VO,om:=SpaceOfHolomorphicDifferentials(F);bb:=[om(v):v in Basis(VO)];bfs:=[b/du:b in bb];factor:=Differential(h(u));TM:=Matrix(k,[Eltseq((h(f)*factor)@@om):f in bfs]);assert TM^2 eq 1;U:=RowSpace(TM-IdentityMatrix(k,10));d4:=eval Read(root cat "paired_p7_degree4_data.m");K<z>:=ext<k|PK!d4[3]>;qt:=[Evaluate(PK!a,z):a in d4[5][which]];cp:=MDPlaceCommonZeros(X`_coordinates,qt);sp,es:=Support(FunctionFieldDivisor(Divisor(cp)));assert #sp eq 1 and es eq[1];N:=sp[1];assert Degree(N)eq 4;a,b:=TwoGenerators(N);assert Valuation(h(a),N)gt 0 and Valuation(h(b),N)gt 0;
old:=eval Read(root cat "relative_cubic_rank.m");OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);cs:=[];for pd in old[3]do O:=pd[2]eq 1 select OF else OI;I:=ideal<O|[DF(c):c in pd[3]]>;assert IsPrime(I);Append(~cs,Place(I));end for;rat:=[i:i in[1..#cs]|Degree(cs[i])eq 1];assert #rat eq 18;out:=[* *];bad:=[];
for i in rat do D:=Divisor(N)+Divisor(cs[i]);V,vm:=DifferentialSpace(D);W:=sub<VectorSpace(k,10)|[Eltseq(vm(v)@@om):v in Basis(V)]>;rk:=Dimension(U)-Dimension(U meet W);assert rk le 3;Append(~out,[*i,rk,[Eltseq(v):v in Basis(W)]*]);if rk ne 3 then Append(~bad,i);end if;end for;
function ER(f)return [[Integers()!c:c in Coefficients(Numerator(f))],[Integers()!c:c in Coefficients(Denominator(f))]];end function;function EF(f)return [ER(c):c in Eltseq(F!f)];end function;function EP(P)a,b:=TwoGenerators(P);assert ideal<Order(Ideal(P))|a,b>eq Ideal(P);return[*Degree(P),IsFinite(P)select 1 else 0,[EF(a),EF(b)]*];end function;
packet:=[*which,pars,inv,EP(N),[EF(hv),EF(hu)],[Eltseq(v):v in Rows(TM)],out,bad*];Write(root cat "relative_quartic_"cat IntegerToString(which)cat".m",Sprint(packet):Overwrite:=true);print "D31B_M318_RELATIVE_QUARTIC_COMPLETE",which,Dimension(U),#out,bad,Cputime(tt);quit;
